#!/usr/bin/env python3
"""Installs the find-leads skill for Claude Code. Run it inside Ubuntu (WSL):

    python3 /mnt/c/Users/USER/Downloads/install_lead_tools.py
"""
import base64
import os
import sys

FILES = {
    'SKILL.md': '',
    'scripts/audit_sites.py': '',
}


def main():
    if os.name == 'nt':
        sys.exit('This is running in Windows. Open Ubuntu instead and run:\n'
                 '  python3 /mnt/c/Users/USER/Downloads/install_lead_tools.py')
    home = os.path.expanduser('~')
    dest = os.path.join(home, '.claude', 'skills', 'find-leads')
    for rel, data in FILES.items():
        path = os.path.join(dest, rel)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(base64.b64decode(data))
    os.makedirs(os.path.join(home, 'leads', 'runs'), exist_ok=True)
    print('Installed the find-leads skill in ' + dest)
    print('')
    print('Next:')
    print('  1. Open Docker Desktop and wait for "Engine running".')
    print('  2. cd ~/leads && claude')
    print('  3. Type, for example:  /find-leads beauty salons in Lekki, Lagos, Nigeria')


if __name__ == '__main__':
    main()
